('Ventidius', 'Ventidius', 'VENTIDIUS', 'timonathens', 'one of Timon''s false friends'),
('Ventidius-ac', 'Ventidius', 'VENTIDIUS', 'antonycleo', 'friend to Antony'),
('verges', 'Verges', 'VERGES', 'muchado', 'A headborough'),
('Vernon', 'Vernon', 'VERNON', 'henry4p1,henry6p1', 'of the White Rose, or York, faction'),
('vincentio', 'Vincentio', 'VINCENTIO', 'tamingshrew', 'a merchant of Pisa'),
('Vincentio-m4m', 'Vincentio', 'DUKE VINCENTIO', 'measure', 'the Duke'),
('Vintner', 'Vintner', 'Vintner', 'henry4p1', ''),
