('VIOLENTA', 'Violenta', 'VIOLENTA', 'allswell', 'neighbor and friend to the widow'),
('virgilia', 'Virgilia', 'VIRGILIA', 'coriolanus', 'wife to Coriolanus'),
('Volsce', 'Volsce', 'Volsce', 'coriolanus', ''),
('voltemand', 'Voltemand', 'Volt', 'hamlet', 'courtier'),
('volumnia', 'Volumnia', 'VOLUMNIA', 'coriolanus', 'mother to Coriolanus'),
('Volumnius', 'Volumnius', 'VOLUMNIUS', 'juliuscaesar', 'friend to Brutus'),
('WalterWhitmore', 'Walter Whitmore', 'WHITMORE', 'henry6p2', ''),
('wart', 'Thomas Wart', 'WART', 'henry4p2', 'country soldier'),
('warwick', 'Earl of Warwick', 'WARWICK', 'henry4p2,henry5,henry6p1,henry6p2,henry6p3', ''),
('Watch-h61', 'Watch', 'Watch', 'henry6p1', ''),
('watchman-ma', 'Watchman', 'Watchman', 'muchado', ''),
('westmoreland', 'Earl of Westmoreland', 'WESTMORELAND', 'henry4p1,henry4p2,henry5,henry6p3', ''),
('widow', 'Widow', 'WIDOW', 'tamingshrew', ''),
('WidowFlorence', 'Widow', 'Widow', 'allswell', 'an old widow of Florence'),
('WifeSimpcox', 'Simpcox''s Wife', 'Wife', 'henry6p2', ''),
('william-ayli', 'William', 'WILLIAM', 'asyoulikeit', 'a country fellow, in love with Audrey'),
('Williams', 'Williams', 'WILLIAMS', 'henry5', 'soldier in King Henry''s army'),
('wmpage', 'William Page', 'WILLIAM PAGE', 'merrywives', 'a boy, son to Page'),
('WmStafford', 'William Stafford', 'WILLIAM STAFFORD', 'henry6p2', 'brother to Sir Humphrey Stafford'),
('Wolsey', 'Cardinal Wolsey', 'CARDINAL WOLSEY', 'henry8', ''),
('Woodvile', 'Woodvile', 'WOODVILE', 'henry6p1', 'lieutenant of the Tower'),
('worcester', 'Earl of Worcester', 'EARL OF WORCESTER', 'henry4p1', ''),
('xxx', '(stage directions)', 'xxx', 'asyoulikeit', ''),
('york', 'Duke of York', 'YORK', 'henry5', 'cousin to the king'),
('YoungClifford', 'Young Clifford', 'YOUNG CLIFFORD', 'henry6p2', ''),
